&lt;ActionGrid&gt;
  &lt;Settings&gt;
    &lt;Version&gt;5.28.0&lt;/Version&gt;
    &lt;Build&gt;5.28.314&lt;/Build&gt;
    &lt;CurrentContext&gt;ExportImport&lt;/CurrentContext&gt;
    &lt;ModuleId&gt;1396&lt;/ModuleId&gt;
    &lt;DataSource&gt;{&quot;DefinitionId&quot;:&quot;SqlQuery&quot;,&quot;Parameters&quot;:{&quot;DbConnector&quot;:{&quot;Type&quot;:&quot;Database&quot;,&quot;Group&quot;:&quot;&quot;,&quot;EntireGroup&quot;:false},&quot;ConnectionString&quot;:&quot;&quot;,&quot;QueryTimeout&quot;:&quot;&quot;,&quot;SqlQuery&quot;:&quot;WITH Sume AS
(
    SELECT &#39;BCR&#39; AS CodBanca, Marca, Suma, Luna, Anul, CodSucursala, TipPlata, DataPlatii, DenumireFisier
    FROM app.SumaBCR

    UNION ALL
    SELECT &#39;BRD&#39;, Marca, Suma, Luna, Anul, CodSucursala, TipPlata, DataPlatii, DenumireFisier
    FROM app.SumaBRD

    UNION ALL
    SELECT &#39;BT&#39;, Marca, Suma, Luna, Anul, CodSucursala, TipPlata, DataPlatii, DenumireFisier
    FROM app.SumaBT

    UNION ALL
    SELECT &#39;CEC&#39;, Marca, Suma, Luna, Anul, CodSucursala, TipPlata, DataPlatii, DenumireFisier
    FROM app.SumaCEC

    UNION ALL
    SELECT &#39;ING&#39;, Marca, Suma, Luna, Anul, CodSucursala, TipPlata, DataPlatii, DenumireFisier
    FROM app.SumaING

    UNION ALL
    SELECT &#39;MIL&#39;, Marca, Suma, Luna, Anul, CodSucursala, TipPlata, DataPlatii, DenumireFisier
    FROM app.SumaMIL

    UNION ALL
    SELECT &#39;RZB&#39;, Marca, Suma, Luna, Anul, CodSucursala, TipPlata, DataPlatii, DenumireFisier
    FROM app.SumaRZB

    UNION ALL
    SELECT &#39;UNI&#39;, Marca, Suma, Luna, Anul, CodSucursala, TipPlata, DataPlatii, DenumireFisier
    FROM app.SumaUNI
)

SELECT
    ROW_NUMBER() OVER
    (
        ORDER BY
            CAST(s.DataPlatii AS DATE),
            bc.CodBanca,
            s.TipPlata
    ) AS Id,

    s.CodSucursala,
    s.Anul,
    s.Luna,

    bc.CodBanca,
    bc.DenumireBanca,

    s.DenumireFisier,

    CAST(s.DataPlatii AS DATE) AS DataPlatii,

    s.TipPlata,

    COUNT(*) AS NumarSalariati,

    SUM(ISNULL(s.Suma,0)) AS ValoareTotala

FROM Sume s

INNER JOIN app.BancaCard bc
    ON bc.CodBanca = s.CodBanca

WHERE s.CodSucursala = @CodSucursala
  AND s.Luna         = @Luna
  AND s.Anul         = @Anul


  AND
(
    TRY_CAST(@DataPlatii AS DATE) IS NULL
    OR CAST(s.DataPlatii AS DATE) = TRY_CAST(@DataPlatii AS DATE)
)
  AND
  (
        @TipPlata IS NULL
        OR @TipPlata = &#39;&#39;
        OR s.TipPlata = @TipPlata
  )
GROUP BY
    s.CodSucursala,
    s.Anul,
    s.Luna,
    bc.CodBanca,
    bc.DenumireBanca,
    s.DenumireFisier,
    CAST(s.DataPlatii AS DATE),
    s.TipPlata;&quot;,&quot;BindTokens&quot;:[{&quot;value&quot;:&quot;[GetOrSession:BranchV]&quot;,&quot;name&quot;:&quot;CodSucursala&quot;},{&quot;value&quot;:&quot;[GetOrSession:YearV]&quot;,&quot;name&quot;:&quot;Anul&quot;},{&quot;value&quot;:&quot;[GetOrSession:MonthV]&quot;,&quot;name&quot;:&quot;Luna&quot;},{&quot;value&quot;:&quot;[QueryString:DataPlatii]&quot;,&quot;name&quot;:&quot;DataPlatii&quot;},{&quot;value&quot;:&quot;[QueryString:TipPlata]&quot;,&quot;name&quot;:&quot;TipPlata&quot;}],&quot;IdColumn&quot;:&quot;Id&quot;,&quot;SqlQueryColumns&quot;:&quot;&quot;,&quot;SqlQueryInsert&quot;:&quot;&quot;,&quot;SqlQueryUpdate&quot;:&quot;&quot;,&quot;SqlQueryDelete&quot;:&quot;&quot;,&quot;AddUrl&quot;:&quot;&quot;,&quot;EditUrl&quot;:&quot;&quot;,&quot;ViewUrl&quot;:&quot;&quot;},&quot;Fields&quot;:[{&quot;Title&quot;:&quot;Id&quot;,&quot;Name&quot;:&quot;Id&quot;,&quot;TypeStr&quot;:&quot;System.Int64, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:true,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:&quot;CodSucursala&quot;,&quot;Name&quot;:&quot;CodSucursala&quot;,&quot;TypeStr&quot;:&quot;System.String, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:true,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:&quot;Anul&quot;,&quot;Name&quot;:&quot;Anul&quot;,&quot;TypeStr&quot;:&quot;System.Int32, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:true,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:&quot;Luna&quot;,&quot;Name&quot;:&quot;Luna&quot;,&quot;TypeStr&quot;:&quot;System.Int32, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:true,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:&quot;CodBanca&quot;,&quot;Name&quot;:&quot;CodBanca&quot;,&quot;TypeStr&quot;:&quot;System.String, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:true,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:&quot;DenumireBanca&quot;,&quot;Name&quot;:&quot;DenumireBanca&quot;,&quot;TypeStr&quot;:&quot;System.String, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:true,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:&quot;DenumireFisier&quot;,&quot;Name&quot;:&quot;DenumireFisier&quot;,&quot;TypeStr&quot;:&quot;System.String, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:true,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:&quot;DataPlatii&quot;,&quot;Name&quot;:&quot;DataPlatii&quot;,&quot;TypeStr&quot;:&quot;System.DateTime, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:true,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:&quot;TipPlata&quot;,&quot;Name&quot;:&quot;TipPlata&quot;,&quot;TypeStr&quot;:&quot;System.String, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:true,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:&quot;NumarSalariati&quot;,&quot;Name&quot;:&quot;NumarSalariati&quot;,&quot;TypeStr&quot;:&quot;System.Int32, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:true,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:&quot;ValoareTotala&quot;,&quot;Name&quot;:&quot;ValoareTotala&quot;,&quot;TypeStr&quot;:&quot;System.Decimal, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:true,&quot;DefaultValue&quot;:null}]}&lt;/DataSource&gt;
    &lt;ShowTitle&gt;True&lt;/ShowTitle&gt;
    &lt;NoDataMessage&gt;No Data&lt;/NoDataMessage&gt;
