    &lt;FiltersEnabled&gt;True&lt;/FiltersEnabled&gt;
    &lt;ShowFilters&gt;False&lt;/ShowFilters&gt;
    &lt;SyncUrl&gt;False&lt;/SyncUrl&gt;
    &lt;IncludeBootstrapJS&gt;True&lt;/IncludeBootstrapJS&gt;
    &lt;IncludeBootstrapCSS&gt;True&lt;/IncludeBootstrapCSS&gt;
    &lt;IncludeFontAwesome&gt;True&lt;/IncludeFontAwesome&gt;
    &lt;AngularnoConflict&gt;True&lt;/AngularnoConflict&gt;
    &lt;SelectAllPosition&gt;None&lt;/SelectAllPosition&gt;
    &lt;SearchPosition&gt;top&lt;/SearchPosition&gt;
    &lt;RootCSSClasses /&gt;
    &lt;ModalRefresh&gt;False&lt;/ModalRefresh&gt;
    &lt;ShowLoading&gt;True&lt;/ShowLoading&gt;
    &lt;TabsProLoading&gt;True&lt;/TabsProLoading&gt;
    &lt;EnableGridSelect&gt;True&lt;/EnableGridSelect&gt;
    &lt;DataSourceAutoRefreshInterval&gt;1&lt;/DataSourceAutoRefreshInterval&gt;
    &lt;DataSourceRefreshType&gt;manual&lt;/DataSourceRefreshType&gt;
    &lt;DateFormat&gt;m/d/yy&lt;/DateFormat&gt;
    &lt;ItemButtonGroups&gt;[]&lt;/ItemButtonGroups&gt;
    &lt;GridButtonGroups&gt;[]&lt;/GridButtonGroups&gt;
    &lt;ItemButtons&gt;[{&quot;ItemActions&quot;:[{&quot;Id&quot;:-1,&quot;IsDeleted&quot;:false,&quot;ActionInfo&quot;:{&quot;Id&quot;:-1,&quot;GlobalId&quot;:&quot;164fe57e-77b3-49ff-8308-441226e535cd&quot;,&quot;Description&quot;:null,&quot;ActionErrorMessage&quot;:null,&quot;ActionStackId&quot;:-1,&quot;ActionType&quot;:&quot;PlantAnApp.ExecuteWorkflow.38dd581d8bb2480d9db883f8a3831de3&quot;,&quot;Condition&quot;:null,&quot;IsDeleted&quot;:false,&quot;IsDisabled&quot;:false,&quot;OrderIndex&quot;:0,&quot;DiagramUID&quot;:null,&quot;ActionParameters&quot;:null,&quot;Parameters&quot;:{&quot;InputHelpText&quot;:null,&quot;CodSucursala&quot;:&quot;[GetOrSession:BranchV]&quot;,&quot;CodBanca&quot;:&quot;[CodBanca]&quot;,&quot;Anul&quot;:&quot;[GetOrSession:YearV]&quot;,&quot;Luna&quot;:&quot;[GetOrSession:MonthV]&quot;,&quot;DataPlatii&quot;:&quot;[QueryString:DataPlatii]&quot;,&quot;TipPlata&quot;:&quot;[QueryString:TipPlata]&quot;,&quot;DenumireFisier&quot;:&quot;[DenumireFisier]&quot;,&quot;OnError&quot;:[],&quot;ContinueOnError&quot;:false},&quot;Metadata&quot;:{},&quot;HasActionParameters&quot;:true}},{&quot;Id&quot;:-1,&quot;IsDeleted&quot;:false,&quot;ActionInfo&quot;:{&quot;Id&quot;:-1,&quot;GlobalId&quot;:&quot;ee015e25-9ab3-44d2-9bfa-d7631327b2b5&quot;,&quot;Description&quot;:null,&quot;ActionErrorMessage&quot;:null,&quot;ActionStackId&quot;:-1,&quot;ActionType&quot;:&quot;ShowToast&quot;,&quot;Condition&quot;:null,&quot;IsDeleted&quot;:false,&quot;IsDisabled&quot;:false,&quot;OrderIndex&quot;:1,&quot;DiagramUID&quot;:null,&quot;ActionParameters&quot;:null,&quot;Parameters&quot;:{&quot;Heading&quot;:&quot;Salvare Fisier&quot;,&quot;Message&quot;:&quot;&amp;lt;p&amp;gt;Fisierul s-a salvat cu SUCCES!&amp;lt;/p&amp;gt;&quot;,&quot;Icon&quot;:{&quot;IsExpression&quot;:false,&quot;Expression&quot;:&quot;&quot;,&quot;Value&quot;:&quot;default&quot;},&quot;BgColor&quot;:null,&quot;Transition&quot;:{&quot;IsExpression&quot;:false,&quot;Expression&quot;:&quot;&quot;,